import React from "react";

export default function MateriauTable({ materiaux }) {
    return (
        <table className="min-w-full border border-gray-300">
            <thead className="bg-gray-200">
            <tr>
                <th className="border p-2">Nom</th>
                <th className="border p-2">Quantité</th>
                <th className="border p-2">Coût</th>
            </tr>
            </thead>
            <tbody>
            {materiaux.map((m, index) => (
                <tr key={index}>
                    <td className="border p-2">{m.nomMateriau}</td>
                    <td className="border p-2">{m.quantite}</td>
                    <td className="border p-2">{m.cout}</td>
                </tr>
            ))}
            </tbody>
        </table>
    );
}
